import { CounterType, CounterComponent } from '@kit.ArkUI';
@Entry
@Component
struct NumberStyleExample {
  build() {
    Column() {
      // Inline numeric counter
      CounterComponent({
        options: {
          type: CounterType.INLINE,
          inlineOptions: {
            value: 100,
            min: 10,
            step: 2,
            max: 1000,
            textWidth: 100,
            onChange: (value: number) => {
              console.info('onCounterChange Counter: ' + value.toString());
            }
          }
        }
      })
    }
  }
}

